1 | /*
2 |  * map.css
3 |  * -------
4 |  * Styles for the storyteller webviews. Colours come from the host theme so the
5 |  * map looks native in VS Code, IBM Bob and in a plain browser (fallbacks).
6 |  * No emoji, no decorative gradients: the layout carries the meaning.
7 |  */
8 | 
9 | :root {
10 |   --ink: var(--vscode-foreground, #1f2328);
11 |   --muted: var(--vscode-descriptionForeground, #5b6673);
12 |   --line: var(--vscode-panel-border, #d8dee6);
13 |   --panel: var(--vscode-sideBar-background, #f6f8fa);
14 |   --editor: var(--vscode-editor-background, #ffffff);
15 |   --accent: var(--vscode-textLink-foreground, #0969da);
16 |   --badge: var(--vscode-badge-background, #e8f0f9);
17 |   --badge-ink: var(--vscode-badge-foreground, #0969da);
18 |   --warn: var(--vscode-editorWarning-foreground, #9a6700);
19 |   --danger: var(--vscode-errorForeground, #cf222e);
20 |   --ok: var(--vscode-testing-iconPassed, #1a7f37);
21 |   --hover: var(--vscode-list-hoverBackground, rgba(0, 0, 0, 0.05));
22 |   --selected: var(--vscode-list-activeSelectionBackground, rgba(9, 105, 218, 0.12));
23 |   --mono: var(--vscode-editor-font-family, "Cascadia Mono", Consolas, monospace);
24 |   --ui: var(--vscode-font-family, "Segoe UI", system-ui, sans-serif);
25 | }
26 | 
27 | body.vscode-dark,
28 | body.vscode-high-contrast {
29 |   --ink: var(--vscode-foreground, #e6edf3);
30 |   --muted: var(--vscode-descriptionForeground, #8b949e);
