45 |   body:not(.vscode-light) {
46 |     --ink: var(--vscode-foreground, #e6edf3);
47 |     --muted: var(--vscode-descriptionForeground, #8b949e);
48 |     --line: var(--vscode-panel-border, #30363d);
49 |     --panel: var(--vscode-sideBar-background, #161b22);
50 |     --editor: var(--vscode-editor-background, #0d1117);
51 |     --accent: var(--vscode-textLink-foreground, #58a6ff);
52 |     --badge: var(--vscode-badge-background, #21262d);
53 |     --badge-ink: var(--vscode-badge-foreground, #79c0ff);
54 |     --warn: var(--vscode-editorWarning-foreground, #d29922);
55 |     --danger: var(--vscode-errorForeground, #f85149);
56 |     --ok: var(--vscode-testing-iconPassed, #3fb950);
57 |     --hover: var(--vscode-list-hoverBackground, rgba(255, 255, 255, 0.08));
