--- file:///c%3A/Users/Harsh/Desktop/ibm-bob-polyglot-navigator/brag-output/composition/index.html
+++ file:///c%3A/Users/Harsh/Desktop/ibm-bob-polyglot-navigator/brag-output/composition/index.html
@@ -0,0 +1,1132 @@
+<!DOCTYPE html>
+<html lang="en">
+<head>
+<meta charset="UTF-8">
+<title>Architecture Storyteller 2.0 — Brag Video</title>
+<meta name="hyperframes-version" content="1">
+<style>
+  /* ── Reset & base ── */
+  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
+  html, body { width: 1920px; height: 1080px; overflow: hidden; background: #0d1117; }
+
+  /* ── Colour tokens ── */
+  :root {
+    --bg:       #0d1117;
+    --surface:  #161b22;
+    --border:   #30363d;
+    --text:     #e6edf3;
+    --muted:    #8b949e;
+    --accent:   #58a6ff;
+    --blue-dk:  #12467b;
+    --green:    #3fb950;
+    --amber:    #d29922;
+    --red:      #f85149;
+    --mono:     "Cascadia Mono", Consolas, monospace;
+    --sans:     "Segoe UI", system-ui, sans-serif;
+  }
+
+  /* ── Scene shell ── */
+  .scene {
+    position: absolute;
+    inset: 0;
+    display: flex;
+    flex-direction: column;
+    align-items: center;
+    justify-content: center;
+    background: var(--bg);
+    opacity: 0;
+  }
+
+  /* ── Typography ── */
+  .headline {
+    font: 600 60px/1.2 var(--sans);
+    color: var(--text);
+    text-align: center;
+    letter-spacing: -0.5px;
+  }
+  .headline-lg {
+    font: 700 80px/1.15 var(--sans);
+    color: var(--text);
+    text-align: center;
+    letter-spacing: -1px;
+  }
+  .sub {
+    font: 400 22px/1.5 var(--sans);
+    color: var(--muted);
+    text-align: center;
+    margin-top: 18px;
+  }
+  .label {
+    font: 600 24px/1.4 var(--sans);
+    color: var(--text);
+    text-align: center;
+    margin-top: 28px;
+  }
+  .kicker {
+    font: 600 13px/1 var(--sans);
+    letter-spacing: 3px;
+    text-transform: uppercase;
+    color: var(--muted);
+    margin-bottom: 16px;
+  }
+  .mono-text {
+    font-family: var(--mono);
+    font-size: 18px;
+    color: var(--text);
+  }
+  .accent { color: var(--accent); }
+  .green-text { color: var(--green); }
+  .amber-text { color: var(--amber); }
+  .red-text { color: var(--red); }
+
+  /* ── Status bar pill ── */
+  .status-bar {
+    display: inline-flex;
+    align-items: center;
+    gap: 8px;
+    background: rgba(210, 153, 34, 0.15);
+    border: 1px solid var(--amber);
+    border-radius: 6px;
+    padding: 10px 22px;
+    font: 600 20px/1 var(--mono);
+    color: var(--amber);
+  }
+  .status-ok {
+    background: rgba(63, 185, 80, 0.12);
+    border-color: var(--green);
+    color: var(--green);
+  }
+  .status-error {
+    background: rgba(241, 81, 73, 0.15);
+    border-color: var(--red);
+    color: var(--red);
+  }
+
+  /* ── Explorer panel ── */
+  .explorer {
+    width: 520px;
+    background: var(--surface);
+    border: 1px solid var(--border);
+    border-radius: 10px;
+    overflow: hidden;
+  }
+  .explorer-header {
+    padding: 12px 18px;
+    font: 600 12px/1 var(--sans);
+    letter-spacing: 1.5px;
+    text-transform: uppercase;
+    color: var(--muted);
+    border-bottom: 1px solid var(--border);
+  }
+  .explorer-file {
+    display: flex;
+    align-items: center;
+    gap: 10px;
+    padding: 10px 18px;
+    font: 400 17px/1 var(--mono);
+    color: var(--text);
+    border-bottom: 1px solid rgba(48,54,61,0.5);
+  }
+  .badge {
+    width: 14px;
+    height: 14px;
+    border-radius: 50%;
+    flex-shrink: 0;
+  }
+  .badge-red    { background: var(--red); box-shadow: 0 0 6px var(--red); }
+  .badge-amber  { background: var(--amber); box-shadow: 0 0 6px var(--amber); }
+  .badge-green  { background: var(--green); box-shadow: 0 0 6px var(--green); }
+
+  /* ── Graph canvas area ── */
+  .graph-canvas {
+    position: relative;
+    width: 860px;
+    height: 500px;
+  }
+  .graph-node {
+    position: absolute;
+    background: var(--surface);
+    border: 2px solid var(--accent);
+    border-radius: 8px;
+    padding: 12px 20px;
+    font: 600 16px/1 var(--mono);
+    color: var(--accent);
+    white-space: nowrap;
+  }
+  .graph-edge {
+    position: absolute;
+    height: 2px;
+    background: var(--accent);
+    opacity: 0.4;
+    transform-origin: left center;
+  }
+
+  /* ── Hover card ── */
+  .hover-card {
+    width: 600px;
+    background: var(--surface);
+    border: 1px solid var(--border);
+    border-left: 3px solid var(--accent);
+    border-radius: 8px;
+    padding: 22px 28px;
+  }
+  .hover-card-title {
+    font: 700 20px/1 var(--mono);
+    color: var(--accent);
+    margin-bottom: 14px;
+    padding-bottom: 10px;
+    border-bottom: 1px solid var(--border);
+  }
+  .hover-row {
+    display: flex;
+    gap: 10px;
+    margin-bottom: 8px;
+    font: 400 15px/1.4 var(--mono);
+    color: var(--text);
+  }
+  .hover-key { color: var(--muted); width: 220px; flex-shrink: 0; }
+
+  /* ── Diff panel ── */
+  .diff-container {
+    display: grid;
+    grid-template-columns: 1fr 1fr;
+    gap: 16px;
+    width: 1400px;
+  }
+  .diff-panel {
+    background: var(--surface);
+    border: 1px solid var(--border);
+    border-radius: 8px;
+    overflow: hidden;
+  }
+  .diff-header {
+    padding: 10px 16px;
+    background: rgba(48,54,61,0.5);
+    font: 600 13px/1 var(--mono);
+    color: var(--muted);
+    border-bottom: 1px solid var(--border);
+  }
+  .diff-body {
+    padding: 16px;
+    font: 400 14px/1.7 var(--mono);
+    color: var(--text);
+  }
+  .diff-add { color: var(--green); background: rgba(63,185,80,0.08); display: block; padding: 0 4px; border-radius: 3px; }
+  .diff-comment { color: var(--amber); }
+
+  /* ── Blast radius card ── */
+  .blast-card {
+    width: 760px;
+    background: var(--surface);
+    border: 2px solid var(--red);
+    border-radius: 12px;
+    padding: 32px 40px;
+    box-shadow: 0 0 40px rgba(241,81,73,0.2);
+  }
+  .blast-card-title {
+    font: 700 36px/1 var(--sans);
+    color: var(--red);
+    margin-bottom: 16px;
+  }
+  .blast-divider {
+    border: none;
+    border-top: 1px solid var(--border);
+    margin: 14px 0;
+  }
+  .blast-stat {
+    font: 600 18px/1.5 var(--mono);
+    color: var(--text);
+  }
+  .blast-card-green {
+    border-color: var(--green);
+    box-shadow: 0 0 40px rgba(63,185,80,0.2);
+  }
+  .blast-card-green .blast-card-title { color: var(--green); }
+
+  /* ── Affected files list ── */
+  .affected-list {
+    width: 700px;
+    margin-top: 24px;
+  }
+  .affected-row {
+    display: flex;
+    align-items: center;
+    justify-content: space-between;
+    padding: 10px 16px;
+    background: var(--surface);
+    border: 1px solid var(--border);
+    border-radius: 6px;
+    margin-bottom: 8px;
+    font: 400 16px/1 var(--mono);
+    color: var(--text);
+  }
+  .affected-count { color: var(--muted); font-size: 13px; }
+
+  /* ── Dossier panel ── */
+  .dossier-panel {
+    width: 1200px;
+    background: var(--surface);
+    border: 1px solid var(--border);
+    border-radius: 12px;
+    overflow: hidden;
+  }
+  .dossier-cover {
+    background: var(--blue-dk);
+    padding: 32px 40px;
+  }
+  .dossier-cover-kicker { font: 600 11px/1 var(--sans); letter-spacing: 3px; text-transform: uppercase; color: rgba(230,237,243,0.6); }
+  .dossier-cover-title { font: 700 36px/1.2 var(--sans); color: var(--text); margin-top: 10px; }
+  .dossier-tabs {
+    display: flex;
+    gap: 0;
+    border-bottom: 1px solid var(--border);
+  }
+  .dossier-tab {
+    padding: 12px 24px;
+    font: 600 14px/1 var(--sans);
+    color: var(--muted);
+    border-bottom: 2px solid transparent;
+  }
+  .dossier-tab.active { color: var(--accent); border-bottom-color: var(--accent); }
+  .dossier-body { padding: 24px 32px; }
+  .kpi-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; margin-bottom: 20px; }
+  .kpi-card {
+    background: var(--bg);
+    border: 1px solid var(--border);
+    border-radius: 8px;
+    padding: 16px 20px;
+  }
+  .kpi-num { font: 700 32px/1 var(--sans); color: var(--accent); }
+  .kpi-label { font: 400 13px/1.4 var(--sans); color: var(--muted); margin-top: 4px; }
+  .terminal-line {
+    font: 400 15px/1.6 var(--mono);
+    color: var(--green);
+    background: rgba(0,0,0,0.4);
+    padding: 12px 16px;
+    border-radius: 6px;
+    margin-top: 12px;
+  }
+
+  /* ── Security table ── */
+  .sec-table {
+    width: 1100px;
+    border-radius: 10px;
+    overflow: hidden;
+    border: 1px solid var(--border);
+  }
+  .sec-row {
+    display: grid;
+    grid-template-columns: 1fr auto;
+    align-items: center;
+    padding: 16px 28px;
+    border-bottom: 1px solid var(--border);
+    font: 400 18px/1 var(--sans);
+    color: var(--text);
+    background: var(--surface);
+  }
+  .sec-row:nth-child(odd) { background: rgba(22,27,34,0.6); }
+  .sec-status { font: 600 14px/1 var(--sans); color: var(--green); display: flex; align-items: center; gap: 6px; }
+
+  /* ── Stat cards ── */
+  .stat-grid { display: flex; gap: 24px; }
+  .stat-card {
+    width: 260px;
+    background: var(--surface);
+    border: 1px solid var(--border);
+    border-radius: 12px;
+    padding: 28px 32px;
+    text-align: center;
+  }
+  .stat-num { font: 700 56px/1 var(--sans); color: var(--accent); }
+  .stat-label { font: 400 15px/1.4 var(--sans); color: var(--muted); margin-top: 8px; }
+
+  /* ── Logo lockup ── */
+  .logo-rule { width: 56px; height: 3px; background: var(--blue-dk); border-radius: 2px; margin: 16px auto; }
+  .logo-title { font: 650 48px/1.1 var(--sans); color: var(--text); text-align: center; letter-spacing: -0.5px; }
+  .logo-sub   { font: 400 26px/1 var(--sans); color: var(--accent); text-align: center; margin-top: 10px; }
+  .logo-tagline { font: 400 16px/1 var(--sans); color: var(--muted); text-align: center; font-style: italic; margin-top: 20px; }
+
+  /* ── Code editor mock ── */
+  .editor-pane {
+    width: 1100px;
+    background: var(--surface);
+    border: 1px solid var(--border);
+    border-radius: 10px;
+    overflow: hidden;
+  }
+  .editor-tab-bar {
+    display: flex;
+    gap: 0;
+    background: rgba(13,17,23,0.8);
+    border-bottom: 1px solid var(--border);
+  }
+  .editor-tab {
+    padding: 10px 20px;
+    font: 400 13px/1 var(--mono);
+    color: var(--muted);
+    border-right: 1px solid var(--border);
+  }
+  .editor-tab.active { color: var(--text); background: var(--surface); border-bottom: 1px solid var(--surface); }
+  .editor-body { padding: 20px 24px; }
+  .code-line { font: 400 15px/1.8 var(--mono); color: var(--text); }
+  .code-kw { color: #ff7b72; }
+  .code-fn { color: #d2a8ff; }
+  .code-param { color: #ffa657; }
+  .code-str { color: #a5d6ff; }
+  .code-comment { color: var(--muted); font-style: italic; }
+
+  /* ── Context menu mock ── */
+  .ctx-menu {
+    background: var(--surface);
+    border: 1px solid var(--border);
+    border-radius: 6px;
+    width: 340px;
+    overflow: hidden;
+    box-shadow: 0 8px 32px rgba(0,0,0,0.5);
+  }
+  .ctx-item {
+    padding: 9px 16px;
+    font: 400 14px/1 var(--sans);
+    color: var(--text);
+  }
+  .ctx-item.active { background: var(--accent); color: #fff; }
+  .ctx-divider { border: none; border-top: 1px solid var(--border); margin: 4px 0; }
+
+  /* ── Cursor dot ── */
+  .cursor {
+    position: absolute;
+    width: 12px;
+    height: 20px;
+    border-left: 2px solid var(--text);
+    animation: blink 1s step-end infinite;
+  }
+  @keyframes blink { 0%,100%{opacity:1} 50%{opacity:0} }
+
+  /* ── Typing animation ── */
+  .typing-line { overflow: hidden; white-space: nowrap; width: 0; }
+</style>
+</head>
+<body data-duration="110" data-fps="30" data-width="1920" data-height="1080">
+
+<!-- ═══════════════════════════════════════════════════
+     AUDIO TRACKS
+     Music: track-index 10 (low priority)
+     SFX:   track-index 11–30 (each unique per clip)
+     VO:    track-index 3  (voice, volume 1.0)
+     ═══════════════════════════════════════════════════ -->
+
+<!-- Music bed — vol 0.32, fade in via tween, fade out at 107s -->
+<audio id="music"
+  data-start="0"
+  data-duration="110"
+  data-track-index="10"
+  data-volume="0.32"
+  src="assets/music/happy-beats-business-moves-vol-12-by-ende-dot-app.mp3">
+</audio>
+
+<!-- Voiceover — full 107.8s, vol 1.0 -->
+<audio id="vo"
+  data-start="0"
+  data-duration="107.8"
+  data-track-index="3"
+  data-volume="1"
+  src="assets/voiceover.wav">
+</audio>
+
+<!-- SFX: Scene 1 — status bar bong at 1.4s -->
+<audio data-start="1.4" data-duration="0.5" data-track-index="11" data-volume="0.55"
+  src="assets/sfx/interface/bong_001.ogg"></audio>
+
