arguments.command:
# Read the file, add ids to audio elements and class="clip" to all timed divs/elements
$content = Get-Content "brag-output\composition\index.html" -Raw

# Add id to every <audio> that has data-start but no id
$counter = 0
$content = [regex]::Replace($content, '(<audio )(?!.*\bid=)(data-start)', {
    param($m)
    $script:counter++
    $m.Groups[1].Value + "id=`"sfx-$($script:counter)`" " + $m.Groups[2].Value
})

# Add class="clip" to every element that has data-start= but is missing class="clip"
# Pattern: opening tag with data-start but no class="clip"
# Strategy: add clip to the class attribute if it exists, or add class="clip" if not
$content = [regex]::Replace($content, '(<(?:div|audio)[^>]+data-start="[^"]*"[^>]*)(>)', {
    param($m)
    $tag = $m.Groups[1].Value
    $close = $m.Groups[2].Value
    # If already has class="clip" or class="... clip ..." skip
    if ($tag -match 'class="[^"]*\bclip\b') {
        return $m.Value
    }
    # If has class="..." without clip, append clip
    if ($tag -match 'class="([^"]*)"') {
        $tag = $tag -replace 'class="([^"]*)"', 'class="$1 clip"'
    } else {
        $tag = $tag + ' class="clip"'
    }
    return $tag + $close
})

Set-Content "brag-output\composition\index.html" -Value $content -NoNewline
Write-Host "Done. Audio IDs added: $counter"

